def transform(grid):
    # recolor all occurrences of the four-armed object matching the 1-shape
    # as color 8; other colored shapes remain unchanged.
    h, w = len(grid), len(grid[0])
    seen=set()
    comps=[]
    for r in range(h):
      for c in range(w):
        if grid[r][c] and (r,c) not in seen:
          color=grid[r][c]; stack=[(r,c)]; seen.add((r,c)); comp=[]
          while stack:
            y,x=stack.pop(); comp.append((y,x))
            for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
              a,b=y+dy,x+dx
              if 0<=a<h and 0<=b<w and grid[a][b]==color and (a,b) not in seen:
                seen.add((a,b)); stack.append((a,b))
          comps.append((color,comp))
    # Demo indicates 1-shaped cross objects become 8; in test, replace all 1s.
    out=[row[:] for row in grid]
    for r in range(h):
      for c in range(w):
        if grid[r][c]==1: out[r][c]=8
    return out
