def transform(grid):
    # The 8-color shape is a marker. Copy its shape/color onto the matching
    # template objects: each color-1 connected object with same size/shape as
    # the marker's 8-pixel object is recolored to 8. In the demo, the 1 cross
    # and 8 cross are equal.
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    seen=set(); comps=[]
    for r in range(h):
      for c in range(w):
        if grid[r][c]!=0 and (r,c) not in seen:
          color=grid[r][c]; st=[(r,c)]; seen.add((r,c)); cells=[]
          while st:
            y,x=st.pop(); cells.append((y,x))
            for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
              yy,xx=y+dy,x+dx
              if 0<=yy<h and 0<=xx<w and grid[yy][xx]==color and (yy,xx) not in seen:
                seen.add((yy,xx)); st.append((yy,xx))
          comps.append((color,cells))
    # Match shape by normalized coordinate set. Marker components are all 8s;
    # recolor 1-components whose shape is congruent under translation.
    shapes=[]
    for col,cells in comps:
      if col==8:
        a=min(y for y,x in cells); b=min(x for y,x in cells)
        shapes.append(frozenset((y-a,x-b) for y,x in cells))
    for col,cells in comps:
      if col==1:
        a=min(y for y,x in cells); b=min(x for y,x in cells)
        shape=frozenset((y-a,x-b) for y,x in cells)
        if shape in shapes:
          for y,x in cells: out[y][x]=8
    return out
