def transform(grid):
    # Identify source objects and target objects by shape: each target pattern
    # colored 6/7/8/9 is associated with a same-shape object of color 1,
    # which takes the target's color. Components are 8-connected so diagonal
    # contacts remain part of one object.
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]; seen=set(); comps=[]
    for r in range(h):
      for c in range(w):
        if grid[r][c] and (r,c) not in seen:
          col=grid[r][c]; st=[(r,c)]; seen.add((r,c)); cells=[]
          while st:
            y,x=st.pop(); cells.append((y,x))
            for dy in (-1,0,1):
              for dx in (-1,0,1):
                yy,xx=y+dy,x+dx
                if (dy or dx) and 0<=yy<h and 0<=xx<w and grid[yy][xx]==col and (yy,xx) not in seen:
                  seen.add((yy,xx)); st.append((yy,xx))
          a=min(y for y,x in cells); b=min(x for y,x in cells)
          shape=frozenset((y-a,x-b) for y,x in cells)
          comps.append((col,cells,shape))
    targets={shape:col for col,cells,shape in comps if col!=1}
    for col,cells,shape in comps:
      if col==1 and shape in targets:
        for y,x in cells: out[y][x]=targets[shape]
    return out
